(async () => {
  // ── Find summoned Tulpa on canvas ─────────────────────────────────────────
  const tulpaToken = canvas.tokens.placeables.find(t => t.actor?.name === "Tulpa");
  if (!tulpaToken) {
    ui.notifications.error("No Tulpa found on canvas. Cast Manifest Tulpa first.");
    return;
  }
  const tulpa = tulpaToken.actor;

  // ── Slot count from spell level (2 at 5th, +1 per level above, max 6) ────
  const spellLevel = typeof usageConfig !== "undefined"
    ? (usageConfig?.spell?.slot ?? usageConfig?.slotLevel ?? 5) : 5;
  const totalSlots = Math.min(2 + (spellLevel - 5), 6);

  // ── Modification definitions ──────────────────────────────────────────────
  // type "ae"   → enable a disabled Active Effect flagged with manifest-tulpa.modification = key
  // type "item" → set flag manifest-tulpa.modEnabled = true on named item
  const MODS = [
    // Morphic
    { key:"size-small",      label:"Size Shift → Small",          cost:1, group:"Morphic",    type:"ae"   },
    { key:"size-tiny",       label:"Size Shift → Tiny",           cost:2, group:"Morphic",    type:"ae"   },
    { key:"size-large",      label:"Size Shift → Large",          cost:1, group:"Morphic",    type:"ae"   },
    { key:"size-huge",       label:"Size Shift → Huge",           cost:2, group:"Morphic",    type:"ae"   },
    { key:"size-grg", label:"Size Shift → Gargantuan",     cost:3, group:"Morphic",    type:"ae"   },
    { key:"reinforced-form",       label:"Reinforced Form (+2 AC)",     cost:1, group:"Morphic",    type:"ae"   },
    { key:"vital-surge",           label:"Vital Surge (+30 HP)",        cost:1, group:"Morphic",    type:"ae"   },
    { key:"unsettling-form",       label:"Unsettling Form",             cost:1, group:"Morphic",    type:"item", itemName:"Unsettling Form" },
    // Combat
    { key:"empowered-strikes",     label:"Empowered Strikes (+1d8)",    cost:1, group:"Combat",     type:"ae"   },
    { key:"multiattack",           label:"Multiattack (2 attacks)",     cost:1, group:"Combat",     type:"item", itemName:"Multiattack" },
    { key:"harrowing-presence",    label:"Harrowing Presence (Fear)",   cost:1, group:"Combat",     type:"item", itemName:"Harrowing Presence" },
    { key:"relentless",            label:"Relentless (0HP → 1HP once)", cost:1, group:"Combat",     type:"item", itemName:"Relentless" },
    // Resistance
    { key:"resistance-acid",        label:"Resistance: Acid",        cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-cold",        label:"Resistance: Cold",        cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-fire",        label:"Resistance: Fire",        cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-lightning",   label:"Resistance: Lightning",   cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-necrotic",    label:"Resistance: Necrotic",    cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-radiant",     label:"Resistance: Radiant",     cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-thunder",     label:"Resistance: Thunder",     cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-bludgeoning", label:"Resistance: Bludgeoning", cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-piercing",    label:"Resistance: Piercing",    cost:1, group:"Resistance", type:"ae" },
    { key:"resistance-slashing",    label:"Resistance: Slashing",    cost:1, group:"Resistance", type:"ae" },
    // Movement
    { key:"fly-speed",    label:"Fly Speed (30 ft)",  cost:1, group:"Movement", type:"ae" },
    { key:"swim-speed",   label:"Swim Speed (30 ft)", cost:1, group:"Movement", type:"ae" },
    { key:"spider-climb", label:"Spider Climb",       cost:1, group:"Movement", type:"ae" },
    // Senses
    { key:"tremorsense", label:"Tremorsense 30 ft", cost:1, group:"Senses", type:"ae" },
    // Skills
    { key:"skill-acr", label:"Skill: Acrobatics",     cost:1, group:"Skills", type:"ae" },
    { key:"skill-ani", label:"Skill: Animal Handling", cost:1, group:"Skills", type:"ae" },
    { key:"skill-arc", label:"Skill: Arcana",          cost:1, group:"Skills", type:"ae" },
    { key:"skill-ath", label:"Skill: Athletics",       cost:1, group:"Skills", type:"ae" },
    { key:"skill-dec", label:"Skill: Deception",       cost:1, group:"Skills", type:"ae" },
    { key:"skill-his", label:"Skill: History",         cost:1, group:"Skills", type:"ae" },
    { key:"skill-ins", label:"Skill: Insight",         cost:1, group:"Skills", type:"ae" },
    { key:"skill-itm", label:"Skill: Intimidation",    cost:1, group:"Skills", type:"ae" },
    { key:"skill-inv", label:"Skill: Investigation",   cost:1, group:"Skills", type:"ae" },
    { key:"skill-med", label:"Skill: Medicine",        cost:1, group:"Skills", type:"ae" },
    { key:"skill-nat", label:"Skill: Nature",          cost:1, group:"Skills", type:"ae" },
    { key:"skill-prc", label:"Skill: Perception",      cost:1, group:"Skills", type:"ae" },
    { key:"skill-prf", label:"Skill: Performance",     cost:1, group:"Skills", type:"ae" },
    { key:"skill-per", label:"Skill: Persuasion",      cost:1, group:"Skills", type:"ae" },
    { key:"skill-rel", label:"Skill: Religion",        cost:1, group:"Skills", type:"ae" },
    { key:"skill-slt", label:"Skill: Sleight of Hand", cost:1, group:"Skills", type:"ae" },
    { key:"skill-ste", label:"Skill: Stealth",         cost:1, group:"Skills", type:"ae" },
    { key:"skill-sur", label:"Skill: Survival",        cost:1, group:"Skills", type:"ae" },
    // Special
    { key:"telepathic-link", label:"Telepathic Link", cost:1, group:"Special", type:"item", itemName:"Telepathic Link" },
  ];

  const SIZE_KEYS = new Set(["size-small","size-tiny","size-large","size-huge","size-grg"]);
  const groups = [...new Set(MODS.map(m => m.group))];

  // ── Build dialog HTML ─────────────────────────────────────────────────────
  let html = `
  <style>
    .tm { font-family: var(--font-primary); }
    .tm .counter { text-align:center; font-weight:bold; font-size:1.1em;
      padding:6px; margin-bottom:8px; background:rgba(0,0,0,0.15); border-radius:4px; }
    .tm .counter.over { color:#e74c3c; }
    .tm h4 { margin:8px 0 3px; border-bottom:1px solid var(--color-border-dark);
      font-size:0.85em; text-transform:uppercase; letter-spacing:0.05em; }
    .tm label { display:flex; align-items:center; gap:6px; padding:2px 0;
      cursor:pointer; font-size:0.9em; }
    .tm label:hover { color:var(--color-text-hyperlink); }
    .tm .cost { margin-left:auto; font-size:0.8em; color:#888; }
    .tm input:disabled + span { opacity:0.4; }
  </style>
  <div class="tm">
    <div class="counter" id="tm-counter">Slots used: 0 / ${totalSlots}</div>`;

  for (const group of groups) {
    html += `<h4>${group}</h4>`;
    for (const m of MODS.filter(x => x.group === group)) {
      html += `<label>
        <input type="checkbox" data-key="${m.key}" data-cost="${m.cost}" data-size="${SIZE_KEYS.has(m.key)}">
        <span>${m.label}</span>
        <span class="cost">${m.cost} slot${m.cost > 1 ? "s" : ""}</span>
      </label>`;
    }
  }
  html += `</div>`;

  // ── Show dialog ───────────────────────────────────────────────────────────
  new Dialog({
    title: `Manifest Tulpa — Modifications (${totalSlots} slot${totalSlots > 1 ? "s" : ""})`,
    content: html,
    render: (jq) => {
      const counter = jq.find("#tm-counter")[0];
      const boxes   = jq.find("input[type=checkbox]");
      boxes.on("change", function() {
        // Size shifts are mutually exclusive
        if (this.checked && this.dataset.size === "true")
          jq.find("input[data-size=true]").not(this).prop("checked", false);
        // Recalculate
        let used = 0;
        jq.find("input:checked").each(function(){ used += +this.dataset.cost; });
        counter.textContent = `Slots used: ${used} / ${totalSlots}`;
        counter.classList.toggle("over", used > totalSlots);
        // Lock unchecked boxes when at cap
        jq.find("input:not(:checked)").prop("disabled", used >= totalSlots);
        if (used < totalSlots) boxes.prop("disabled", false);
      });
    },
    buttons: {
      ok: {
        label: "Manifest!",
        callback: async (jq) => {
          let used = 0;
          jq.find("input:checked").each(function(){ used += +this.dataset.cost; });
          if (used > totalSlots) {
            ui.notifications.error(`Over slot limit (${used}/${totalSlots}) — nothing applied.`);
            return;
          }
          const selected = [...jq.find("input:checked")].map(el => el.dataset.key);
          if (!selected.length) { ui.notifications.info("No modifications chosen."); return; }

          const promises = [];
          for (const key of selected) {
            const mod = MODS.find(m => m.key === key);
            if (!mod) continue;
            if (mod.type === "ae") {
              const ae = tulpa.effects.find(e => e.flags?.["manifest-tulpa"]?.modification === key);
              if (ae) promises.push(ae.update({ disabled: false }));
              else ui.notifications.warn(`AE not found: ${mod.label}`);
            } else {
              const it = tulpa.items.getName(mod.itemName);
              if (it) promises.push(it.setFlag("manifest-tulpa", "modEnabled", true));
              else ui.notifications.warn(`Item not found: ${mod.itemName}`);
            }
          }
          await Promise.all(promises);

          // Auto-arm Relentless hook if that mod was selected
          if (selected.includes("relentless")) {
            const relentlessMacro = game.macros.getName("Tulpa - Relentless Hook");
            if (relentlessMacro) await relentlessMacro.execute();
            else ui.notifications.warn("Tulpa - Relentless Hook macro not found — arm it manually.");
          }

          // Set Harrowing Presence save DC from caster's spell DC
          if (selected.includes("harrowing-presence")) {
            const caster = game.user?.character
              ?? game.actors.find(a => a.items.getName("Manifest Tulpa") && a.type === "character");
            const dc = caster?.system?.attributes?.spelldc;
            const hp = tulpa.items.getName("Harrowing Presence");
            if (hp && dc) {
              await hp.update({ "flags.ActiveAuras.savedc": dc });
            } else {
              ui.notifications.warn("Set Harrowing Presence savedc manually — caster not found.");
            }
          }

          ui.notifications.info(`✓ ${selected.length} modification${selected.length > 1 ? "s" : ""} applied to the Tulpa.`);
        }
      },
      cancel: { label: "Cancel" }
    },
    default: "ok"
  }, { width: 420, height: 580 }).render(true);
})();
